// DecodeGetRequest returns a decoder for requests sent to the
// identityProviderConnections get endpoint.
func DecodeGetRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*identityproviderconnections.GetPayload, error) {
	return func(r *http.Request) (*identityproviderconnections.GetPayload, error) {
		var payload *identityproviderconnections.GetPayload
		var (
			id           *string
			apikeyToken  *string
			sessionToken *string
			err          error
		)
		idRaw := r.URL.Query().Get("id")
		if idRaw != "" {
			id = &idRaw
		}
		if id != nil {
			err = goa.MergeErrors(err, goa.ValidateFormat("id", *id, goa.FormatUUID))
		}
		apikeyTokenRaw := r.Header.Get("Gram-Key")
		if apikeyTokenRaw != "" {
			apikeyToken = &apikeyTokenRaw
		}
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewGetPayload(id, apikeyToken, sessionToken)
		if payload.ApikeyToken != nil {
			if strings.Contains(*payload.ApikeyToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.ApikeyToken, " ", 2)[1]
				payload.ApikeyToken = &cred
			}
		}
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

